import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.D7xI0JV8.js";const f=JSON.parse('{"title":"Reputation Proofs (FICO Pack)","description":"","frontmatter":{},"headers":[],"relativePath":"reputation-proofs.md","filePath":"reputation-proofs.md"}'),i={name:"reputation-proofs.md"};function s(d,e,c,n,p,l){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="reputation-proofs-fico-pack" tabindex="-1">Reputation Proofs (FICO Pack) <a class="header-anchor" href="#reputation-proofs-fico-pack" aria-label="Permalink to &quot;Reputation Proofs (FICO Pack)&quot;">​</a></h1><p>Zero-knowledge reputation proofs for obsqra.xyz: prove solvency, risk tier, trader performance, strategy integrity, and execution integrity without revealing private data. Proofs are verified on Starknet via Garaga BN254 verifiers and registered in ObsqraFactRegistry.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Proof</th><th>Endpoint</th><th>Claim</th></tr></thead><tbody><tr><td>Solvency</td><td><code>POST .../reputation/proof/solvency</code></td><td>total_assets ≥ total_liabilities</td></tr><tr><td>Risk Passport</td><td><code>POST .../reputation/proof/risk-passport</code></td><td>risk_tier ≤ required_tier</td></tr><tr><td>Trader Performance</td><td><code>POST .../reputation/proof/performance</code></td><td>Sharpe, drawdown, win rate within bounds</td></tr><tr><td>Strategy Integrity</td><td><code>POST .../reputation/proof/strategy-integrity</code></td><td>Position, leverage, slippage within policy</td></tr><tr><td>Execution Integrity</td><td><code>POST .../reputation/proof/execution-integrity</code></td><td>Delay and price deviation within bounds</td></tr></tbody></table><h2 id="get-proof-status" tabindex="-1">Get proof status <a class="header-anchor" href="#get-proof-status" aria-label="Permalink to &quot;Get proof status&quot;">​</a></h2><p><strong>GET</strong> <code>/api/v1/zkdefi/reputation/proofs/{address}</code></p><p>Returns status of all five proofs for an address.</p><p><strong>Response:</strong> <code>address</code>, <code>proofs</code> (array of <code>{ proof_type, status, generated_at?, proof_hash?, on_chain_verified }</code>), <code>tier</code>, <code>tier_name</code>, <code>total_proofs_complete</code>.</p><ul><li><code>status</code>: <code>&quot;complete&quot;</code> | <code>&quot;pending&quot;</code> | <code>&quot;available&quot;</code>.</li><li>When <code>complete</code>, <code>generated_at</code> (Unix s), <code>proof_hash</code>, and <code>on_chain_verified</code> are set when available.</li></ul><h2 id="generate-proofs" tabindex="-1">Generate proofs <a class="header-anchor" href="#generate-proofs" aria-label="Permalink to &quot;Generate proofs&quot;">​</a></h2><p>Base URL: <code>/api/v1/zkdefi/reputation/proof/</code></p><p>All POST bodies must include <code>user_address</code> (hex). Request/response shapes are in the backend OpenAPI spec; summary:</p><ul><li><strong>solvency</strong>: <code>asset_positions[]</code>, <code>debt_positions[]</code>, <code>min_solvency_ratio_bps</code>.</li><li><strong>risk-passport</strong>: <code>volatility_bps</code>, <code>max_drawdown_bps</code>, <code>concentration_bps</code>, <code>effective_leverage_bps</code>, <code>liquidation_events</code>, <code>tenure_days</code>, <code>required_tier</code> (optional).</li><li><strong>performance</strong>: <code>returns_bps</code> (30), <code>equity_curve</code> (30), plus threshold params.</li><li><strong>strategy-integrity</strong>: <code>position_weights_bps[]</code>, <code>effective_leverage_bps</code>, <code>observed_slippage_bps[]</code>, policy bounds.</li><li><strong>execution-integrity</strong>: <code>submission_block</code>, <code>inclusion_block</code>, <code>expected_price</code>, <code>actual_price</code>, <code>max_delay_blocks</code>, <code>max_price_deviation_bps</code>.</li></ul><p><strong>Response:</strong> Circuit scan result with <code>all_pass</code>, <code>results[]</code> (per-circuit success, proof hash, timing).</p><h2 id="tier-upgrade-flow" tabindex="-1">Tier upgrade flow <a class="header-anchor" href="#tier-upgrade-flow" aria-label="Permalink to &quot;Tier upgrade flow&quot;">​</a></h2><ol><li>Generate required proofs for the target tier (e.g. Risk Passport for Express).</li><li>Call <code>POST /api/v1/zkdefi/reputation/upgrade-tier</code> with <code>address</code>, <code>target_tier</code>, <code>upgrade_proof_hash</code> (placeholder supported for current backend).</li><li>Backend updates tier; frontend Credit &amp; Reputation Hub reflects the new tier and proof status.</li></ol><h2 id="contracts-starknet-sepolia" tabindex="-1">Contracts (Starknet Sepolia) <a class="header-anchor" href="#contracts-starknet-sepolia" aria-label="Permalink to &quot;Contracts (Starknet Sepolia)&quot;">​</a></h2><ul><li><strong>ObsqraFactRegistry</strong>: <code>0x02009ab87f581a0a92f65906ce84664a5cfcb86f7266651f48a04fac3c62faa3</code></li><li>Verifiers: see <a href="/docs/contracts.html">Contracts</a> for SolvencyProofVerifier, RiskPassportTierVerifier, TraderPerformanceVerifier, StrategyIntegrityVerifier, ExecutionIntegrityVerifier addresses.</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>Proofs use BN254 Poseidon hashing for on-chain verification. Private inputs (positions, returns, etc.) are not sent to the API in plain form for production flows; the backend builds witnesses and runs the circuits. See <a href="/docs/reputation-system.html">Reputation system</a> and circuit spec in the repo (<code>circuits/REPUTATION_V1_CIRCUIT_SPEC.md</code>).</p><p>Next: <a href="/docs/api-overview.html">API overview</a> | <a href="/docs/contracts.html">Contracts</a> | <a href="/docs/reputation-system.html">Reputation system</a></p>',21)])])}const h=o(i,[["render",s]]);export{f as __pageData,h as default};
